  "settings.modelProvider.fieldHelp": "Info zu {field}",
  "settings.modelProvider.help.contextWindow":
    "Die Kontextkapazität, die das Modell auf einmal verarbeiten kann, in Token. DeepVibe nutzt sie zur Verwaltung des Kontexts.\nÜberschreite nicht das tatsächliche Limit des Modells.",
  "settings.modelProvider.help.maxOutputTokens":
    "Die maximale Anzahl an Token, die eine einzelne Modellanfrage erzeugen darf.\nÜberschreite nicht das tatsächliche Limit des Modells.",
  "settings.modelProvider.help.inputModalities":
    "Lege die Inhaltstypen fest, die das Modell empfangen kann:\n\n- **Text**: Empfängt Textinhalte. Erforderlich.\n- **Bilder**: Empfängt Bildinhalte.\n- **Video**: Empfängt Videoinhalte.\n- **PDF**: Empfängt PDF-Dokumente direkt.",
  "settings.modelProvider.help.outputModalities":
    "Der Inhaltstyp der Antworten des Modells. Derzeit wird nur Text unterstützt.",
  "settings.modelProvider.help.capabilities":
    "- **Strukturierte Ausgabe**: Unterstützt JSON-Schema-Einschränkungen für Ausgabefelder, Typen und Struktur.\n- **Native Websuche**: Unterstützt die integrierte Websuche der Modell-API.\n- **Systemnachrichten mitten in der Unterhaltung**: Unterstützt das Einfügen von Systemanweisungen während einer Unterhaltung.\n\nAktiviere keine Fähigkeiten, die das Modell nicht unterstützt.",
  "settings.modelProvider.help.reasoningLevelsOrdered":
    "Lege die im Chat verfügbaren Denkstufen fest. **Sie müssen vom geringsten zum höchsten Denkaufwand geordnet sein**.\nKonfiguriere keine Denkstufen, die das Modell nicht unterstützt.",
  "settings.modelProvider.help.reasoningLevelMapping":
    "Verwende einen CEL-Ausdruck, um die aktuelle Denkstufe `reasoningLevel` auf Felder der Modell-API-Anfrage abzubilden. Das vom Ausdruck zurückgegebene JSON-Objekt wird in den ausgehenden Anfrage-Body eingefügt.",
  "settings.modelProvider.help.advanced":
    "**MFJS-Tool-Schema**: Aktiviert die Kompatibilität mit Moonshot Flavored JSON Schema, das üblicherweise von der Kimi-Modell-API von Moonshot verwendet wird. Aktiviere dies nur, wenn die Modell-API dieses Format erfordert.",
  "settings.modelProvider.help.followRecommendedConfig":
    "Übernimmt die empfohlene Konfiguration anhand von Modell-ID, Base-URL und API-Format. DeepVibe aktualisiert die Empfehlungen fortlaufend und synchronisiert sie automatisch mit dir.\nWenn du eine Einstellung manuell änderst, wird diese Einstellung manuell verwaltet und folgt keinen Empfehlungsaktualisierungen mehr; andere Einstellungen bleiben weiterhin durch die intelligente Konfiguration verwaltet.",
